 plan=json.loads((ROOT/'results/strict_pilot_schedule_plan_001.json').read_text());scheduled=[json.loads(s) for s in (ROOT/'results/strict_pilot_schedule_001.jsonl').read_text().splitlines()];assert len(scheduled)==52 and {(r['case'],r['mode']) for r in scheduled}=={(r['case'],r['mode']) for r in plan};rows=[];pids=[];threads=[];code_hashes=[];providers=collections.Counter();methods=collections.Counter();tools=collections.Counter();audit_errors=[]
